pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 initialDeposit, uint256 withdrawAmount) public {
        // Restrict to valid ranges
        initialDeposit = bound(initialDeposit, 1, 100 ether);
        withdrawAmount = bound(withdrawAmount, 1, 10 ether);
        vm.assume(withdrawAmount <= initialDeposit);

        // Fund the contract via fallback
        vm.deal(address(this), initialDeposit);
        (bool sent,) = address(c).call{value: initialDeposit}("");
        require(sent, "initial deposit failed");

        // Record pre-state
        uint256 balanceBefore = address(c).balance;
        uint256 countBefore = c.depositsCount();

        // Deploy a reentrant attacker that drains on receive
        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), 0 ether);

        // Transfer ownership to attacker so it can call withdraw
        vm.prank(c.owner());
        c.sendMoney(address(attacker), 0); // no ETH needed, just trust
        // Actually, ownership cannot be transferred – we prank from owner directly
        // Attacker needs to call withdraw – prank from owner for the call
        vm.prank(c.owner());
        c.withdraw(withdrawAmount);

        // Post-state
        uint256 balanceAfter = address(c).balance;
        uint256 countAfter = c.depositsCount();

        // General invariant: balance + total withdrawn == total ever deposited (count)
        // We track the total deposited as the fallback calls count; each fallback deposits some Ether.
        // Here initialDeposit is the only deposit, and withdrawAmount is attempted withdrawn.
        // Expected final balance: initialDeposit - withdrawAmount (if no reentrancy).
        // With reentrancy, attacker can drain extra, leaving balance = 0 and still withdrawing only once.
        assertEq(balanceAfter, initialDeposit - withdrawAmount, "Invariant broken: balance inconsistency");
    }
}

contract Attacker {
    C public target;
    bool private attacking;

    constructor(C _target) {
        target = _target;
    }

    receive() external payable {
        if (!attacking) {
            attacking = true;
            target.withdraw(address(target).balance);
            attacking = false;
        }
    }
}

