pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seedDeposit, uint256 withdrawAmount, uint256 attackerDeposit) public {
        vm.assume(seedDeposit > 0 && attackerDeposit > 0 && withdrawAmount > 0);
        vm.assume(seedDeposit < 1 ether && attackerDeposit < 1 ether && withdrawAmount < 1 ether);

        // Deploy reentrant attacker
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // Fund one legit deposit from owner
        vm.deal(address(c), seedDeposit);
        vm.prank(address(c)); // force deposit via fallback
        (bool ok,) = address(c).call{value: seedDeposit}("");
        require(ok, "seed deposit");

        // Fund attacker
        vm.deal(address(attacker), attackerDeposit);
        vm.prank(address(attacker));
        attacker.deposit{value: attackerDeposit}();

        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Attacker initiates withdraw
        vm.prank(address(attacker));
        attacker.initiateWithdraw(withdrawAmount);

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Invariant: depositsCount reflects total deposits minus successful withdrawals;
        // balance equals total deposits minus sum(withdrawn). In reference both hold;
        // in buggy reentrant attacker can drain more than withdrawAmount counted once.
        assertTrue((beforeDeposits - afterDeposits) <= 1 || beforeBalance >= afterBalance);
    }
}

contract ReentrantAttacker {
    C public target;
    uint reentrancyCount;

    constructor(address _target) { target = C(_target); }

    function deposit() external payable {}

    function initiateWithdraw(uint amount) external {
        target.withdraw(amount);
    }

    receive() external payable {
        if (reentrancyCount < 10 && address(target).balance >= 1) {
            reentrancyCount++;
            target.withdraw(1);
        }
    }
}

